      {
        "block_id": "doxcnVoIGbz1GgBqpDE8eOcgPUb",
        "block_type": 14,
        "code": {
          "elements": [
            {
              "text_run": {
                "content": "// Create a struct schema and add its subfields\n// add a vector subfield with mmap enabled\nMap<String, String> mmapParams = new HashMap<>();\nmmapParams.put(\"mmap.enabled\", \"true\");\nclient.addCollectionStructField(AddCollectionStructFieldReq.builder()\n        .collectionName(\"books\")\n        .fieldName(\"chunks\")\n        .maxCapacity(1024)\n        .nullable(true)\n        .addStructField(AddFieldReq.builder()\n                .fieldName(\"text\")\n                .dataType(DataType.VarChar)\n                .maxLength(65535)\n                .build())\n        .addStructField(AddFieldReq.builder()\n                .fieldName(\"chapter\")\n                .dataType(DataType.VarChar)\n                .maxLength(512)\n                .build())\n        .addStructField(AddFieldReq.builder()\n                .fieldName(\"text_vector\")\n                .dataType(DataType.FloatVector)\n                .dimension(5)\n                .typeParams(mmapParams)\n                .build())\n        .addStructField(AddFieldReq.builder()\n                .fieldName(\"chapter_vector\")\n                .dataType(DataType.FloatVector)\n                .dimension(5)\n                .typeParams(mmapParams)\n                .build())\n",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
