                }
              }
            },
            {
              "text_run": {
                "content": " no longer returns the dropped Function or its generated vector field. The Function input fields remain in the schema.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
