        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "If removing the Function output field would leave the collection without any vector field, the operation is rejected.",
                "text_element_style": {
