      },
      {
        "block_id": "B1z0ddcLuo3Ys8xJefVcv2Y0nzg",
        "block_type": 2,
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "Use ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "add_collection_field()",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": " to add a user-defined scalar field when your application provides scalar values for filtering, query output, or application logic.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "GNSAd8xHuoR685xwEllcVqwOnCb",
        "block_type": 2,
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "Use ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "add_collection_field()",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": " to add a user-defined vector field when your application generates embeddings and writes vector values to <include target=\"milvus\">Milvus</include><include target=\"zilliz\">Zilliz Cloud</include>.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "doxcnBUPO5gJfmgRZCYskvA6VZb",
        "block_type": 2,
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "Use ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "add_function_field()",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": " when vector values should be generated from existing fields. It adds a Function, its generated vector field, and the bound index definition in the same schema change. This guide shows the BM25 path for lexical search; MinHash Functions generate binary vector fields for near-duplicate detection.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "DEe0dnhy6oo1F0xuhflcQcBGnzb",
        "block_type": 5,
        "heading3": {
          "elements": [
            {
              "text_run": {
                "content": "Why must added user-defined fields be nullable?",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        },
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf"
      },
      {
        "block_id": "V10ad3jBCoaBKxxM3O0cyYX6nie",
        "block_type": 2,
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "Existing entities were inserted before the new field existed, so they do not have values for that field. Setting ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "nullable=True",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": " lets <include target=\"milvus\">Milvus</include><include target=\"zilliz\">Zilliz Cloud</include> represent the missing value as ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "NULL",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": " until your application writes a value or, for scalar fields, until a default value applies.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "doxcnBswXcUISl43Y9P3YJ5zbUb",
        "block_type": 2,
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "This rule applies to user-defined scalar fields and user-defined vector fields added with ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "add_collection_field()",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": ". It does not apply to a Function's generated vector field, which cannot be nullable.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "ZsTxdO7DkoQH7rxWQW6cIoc1nhb",
        "block_type": 5,
        "heading3": {
          "elements": [
            {
              "text_run": {
                "content": "What happens to existing entities after I add a user-defined field?",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        },
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf"
      },
      {
        "block_id": "XSX0dwiOKotQ5dxcFYIcxgMHnpc",
        "block_type": 2,
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "For a user-defined scalar field, existing entities return ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "NULL",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": " unless you set a ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "default_value",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": ". If you set a ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "default_value",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": ", existing entities return that default value.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "HosVdizReoyehpxbEoEcoHyNnmc",
        "block_type": 2,
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "For a user-defined vector field, existing entities have ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "NULL",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": " for the new vector field. Vector search on the added field skips entities whose vector value is ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "NULL",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": ". To make existing entities searchable through the new vector field, write non-NULL vector values through upsert or a backfill workflow. New entities can include the new vector field during insert.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "QZdSd529FoKG7dxkYlWck2Mtn6A",
        "block_type": 5,
        "heading3": {
          "elements": [
            {
              "text_run": {
                "content": "Can I add a BM25 Function and its generated sparse vector field to an existing collection?",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        },
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf"
      },
      {
        "block_id": "doxcnMWcH3GISlHlI9e1jcG6L4e",
        "block_type": 2,
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "Yes. If the collection already has a ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "VARCHAR",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": " field with analyzer enabled, you can add a BM25 Function and its generated sparse vector field for lexical search. This operation adds the Function, the new ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "SPARSE_FLOAT_VECTOR",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": " output field, and the bound index definition in the same schema change. You cannot use an existing ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "TEXT",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": " field as the BM25 input in this schema-change workflow. To use ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "TEXT",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": ", define the field and BM25 Function when you create the collection; otherwise, recreate or migrate the collection with the Function in its schema.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "doxcnP2TQ1O15fMLlmMFockSI7g",
        "block_type": 2,
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "When calling ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
