          }
        },
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf"
      },
      {
        "block_id": "doxcnWegVpyAnEL999ax5GF9OTd",
        "block_type": 2,
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "Call ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "drop_function_field()",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": " with the Function name. This operation removes the Function, its generated vector field, and the associated index together while preserving the Function input fields.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "DDFpd3eMHoYTWVx9a7UchL6jnqc",
        "block_type": 5,
        "heading3": {
          "elements": [
            {
              "text_run": {
                "content": "Do I need to wait after altering a collection schema?",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        },
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf"
      },
      {
        "block_id": "Gm1qdA5yMoUp3qxnxDKcWwD9nvf",
        "block_type": 2,
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "Usually, no manual wait is required. If your next operation depends on the updated schema, you can call ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "describe_collection()",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": " first to confirm the schema that <include target=\"milvus\">Milvus</include><include target=\"zilliz\">Zilliz Cloud</include> currently returns.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "doxcnuAJ9Fpy2HJkDuIgyDb5mCe",
        "block_type": 5,
        "heading3": {
          "elements": [
            {
              "text_run": {
                "content": "Why does an added vector sub-field fail with a FieldNotLoaded error?",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        },
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf"
      },
      {
        "block_id": "doxcn2svnWwNhZH2Dq06QaOJh2y",
        "block_type": 2,
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "After you add a vector sub-field and create its index, queries against the new sub-field can still fail with error 2027 (",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "FieldNotLoaded",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": ") even though the collection reports ready. Release the collection and load it again; queries then cover the new sub-field.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "IQf1dnRhiox3SAxo9b6cuRapnoe",
        "block_type": 2,
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "In a distributed deployment, there can be a short propagation window while <include target=\"milvus\">Milvus</include><include target=\"zilliz\">Zilliz Cloud</include> components refresh collection metadata. If an operation immediately after the schema change fails with a schema-related error, refresh the schema and retry the operation.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "SqEVdvqvvow5wRxYByGcJsNwnEf",
        "block_type": 5,
        "heading3": {
          "elements": [
            {
              "text_run": {
                "content": "When is storage space reclaimed after dropping a field?",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        },
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf"
      },
      {
        "block_id": "TNc1d0RBrolvpwxfME1cDOWin2f",
        "block_type": 2,
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "Dropping a field removes it from the current schema and normal query/search visibility, but historical data for that field is not physically deleted from object storage immediately.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "WnHydWTr3oQcubxigQEcbWn2n6g",
        "block_type": 2,
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "Storage space can be reclaimed later during compaction. Compaction is a background process that reorganizes existing data files into new, more compact files. After a field is dropped, newly compacted files follow the current schema and omit the dropped field. <include target=\"milvus\">Milvus</include><include target=\"zilliz\">Zilliz Cloud</include> does not guarantee an immediate or fixed-time storage-space reduction after dropping a field.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "Sm8GdvFHQozWihxM8lXcx6DcnCb",
        "block_type": 5,
        "heading3": {
          "elements": [
            {
              "text_run": {
                "content": "What happens if I add a scalar field with the same name as a dynamic field key?",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        },
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf"
      },
      {
        "block_id": "P2eCdEMN0opaUwxYoKgcIU49n1b",
        "block_type": 2,
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "If dynamic field is enabled, you can add a scalar field with the same name as an existing dynamic field key. The new scalar field masks the dynamic field key in normal query output, but the original dynamic data is preserved in ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "$meta",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": ".",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      },
      {
        "block_id": "S2cKd83SVoKTWIxreUycWTcinGd",
        "block_type": 2,
        "parent_id": "DGkYdgae0oj89YxVxqnccARYnEf",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "For example, if existing entities store a dynamic key named ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "source",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": ", and you later add a scalar field named ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "source",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": ", normal output for ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "source",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": " refers to the scalar field. To access the original dynamic value, use the $meta path syntax, such as ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "$meta[\"source\"]",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": ".",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
      }
