        "block_type": 2,
        "parent_id": "EmRZdpJ1No87NhxLKT1cDFxqnHR",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "You are advised to keep the Struct schema lean by only including fields you'll use for retrieval or display. Avoid bloating with unused metadata.",
