        "block_type": 2,
        "parent_id": "EmRZdpJ1No87NhxLKT1cDFxqnHR",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "Each Array field has an attribute that specifies the maximum number of elements the Array field can hold for each entity. Set this based on your use case's upper bound. For example, there are 1,000 text chunks per document, or 100 maneuvers per driving scene. ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
