        "block_type": 2,
        "parent_id": "EmRZdpJ1No87NhxLKT1cDFxqnHR",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "An excessively high value wastes memory, and you'll need to do some calculations to determine the maximum number of Structs in the Array field.",
