        "text": {
          "elements": [
            {
              "text_run": {
                "content": "An upsert request <include target=\"milvus\">that works in override mode</include> combines an insert and a delete. When an ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "upsert",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": " request for an existing entity is received, <include target=\"milvus\">Milvus</include><include target=\"zilliz\">Zilliz Cloud</include> ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "inserts the data carried in the request payload and deletes the existing entity with the original primary key specified in the data at the same time. ",
                "text_element_style": {
                  "bold": false,
                  "comment_ids": [
                    "7547908666379730947"
                  ],
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
          ],
          "style": {
            "align": 1,
            "folded": false
          }
        }
