        "text": {
          "elements": [
            {
              "text_run": {
                "content": "Zilliz Cloud retrieves the existing entity with a strong-consistency query, merges your changes with the stored data, inserts the merged entity, and deletes the old entity.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
