        "parent_id": "RmCCd1QRBo6nlixUnmMcjr5Xnrg",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "Updating an existing entity in merge mode preserves its primary key, even when ",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": "autoID",
                "text_element_style": {
                  "bold": false,
                  "inline_code": true,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            },
            {
              "text_run": {
                "content": " is enabled. If the primary key does not exist, Zilliz Cloud attempts to insert a new entity. You must provide all fields to insert the new entity; otherwise, the request fails with a missing-field error.",
                "text_element_style": {
                  "bold": false,
                  "inline_code": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false
                }
              }
            }
