        "parent_id": "RmCCd1QRBo6nlixUnmMcjr5Xnrg",
        "text": {
          "elements": [
            {
              "text_run": {
                "content": "If a partial update fails with a missing-field error, check whether the target entity exists. Without an existing entity, Zilliz Cloud cannot retrieve the values of fields you omitted.",
